ALTER TABLE BOLL_GEST_DETT_AUTORIZZ ADD FK_BOLLGEST_ID NUMBER(4,0);
ALTER TABLE BOLL_GEST_DETT_RATE ADD FK_BOLLGEST_ID NUMBER(4,0);
ALTER TABLE BOLL_GEST_ISTANZEONERI ADD FK_BOLLGEST_ID NUMBER(4,0);
ALTER TABLE BOLL_GEST_MERCATI_DETT ADD FK_BOLLGEST_ID NUMBER(4,0);
ALTER TABLE BOLL_GEST_ONERI_SEQUENCE ADD FK_BOLLGEST_ID NUMBER(4,0);

ALTER TABLE BOLL_GEST_DETT_AUTORIZZ ADD CONSTRAINT FK_DETAUT_BLLGSTTEST FOREIGN KEY (IDCOMUNE, FK_BOLLGEST_ID) REFERENCES BOLL_GEST_TESTATA(IDCOMUNE, ID);
ALTER TABLE BOLL_GEST_DETT_RATE ADD CONSTRAINT FK_DETRAT_BLLGSTTEST FOREIGN KEY (IDCOMUNE, FK_BOLLGEST_ID) REFERENCES BOLL_GEST_TESTATA(IDCOMUNE, ID);
ALTER TABLE BOLL_GEST_ISTANZEONERI ADD CONSTRAINT FK_ISTONE_BLLGSTTEST FOREIGN KEY (IDCOMUNE, FK_BOLLGEST_ID) REFERENCES BOLL_GEST_TESTATA(IDCOMUNE, ID);
ALTER TABLE BOLL_GEST_MERCATI_DETT ADD CONSTRAINT FK_MERDET_BLLGSTTEST FOREIGN KEY (IDCOMUNE, FK_BOLLGEST_ID) REFERENCES BOLL_GEST_TESTATA(IDCOMUNE, ID);
ALTER TABLE BOLL_GEST_ONERI_SEQUENCE ADD CONSTRAINT FK_ONESEQ_BLLGSTTEST FOREIGN KEY (IDCOMUNE, FK_BOLLGEST_ID) REFERENCES BOLL_GEST_TESTATA(IDCOMUNE, ID);

CREATE INDEX IDX_DETAUT_BLLGSTTEST_001 ON BOLL_GEST_DETT_AUTORIZZ(IDCOMUNE,FK_BOLLGEST_ID);
CREATE INDEX IDX_DETRAT_BLLGSTTEST_001 ON BOLL_GEST_DETT_RATE(IDCOMUNE,FK_BOLLGEST_ID);
CREATE INDEX IDX_ISTONE_BLLGSTTEST_001 ON BOLL_GEST_ISTANZEONERI(IDCOMUNE,FK_BOLLGEST_ID);
CREATE INDEX IDX_MERDET_BLLGSTTEST_001 ON BOLL_GEST_MERCATI_DETT(IDCOMUNE,FK_BOLLGEST_ID);
CREATE INDEX IDX_ONESEQ_BLLGSTTEST_001 ON BOLL_GEST_ONERI_SEQUENCE(IDCOMUNE,FK_BOLLGEST_ID);

MERGE INTO BOLL_GEST_DETT_AUTORIZZ USING (SELECT IDCOMUNE, ID, FK_BOLLGEST_ID, RNUM FROM (SELECT BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE, BOLL_GEST_DETT_AUTORIZZ.ID, BOLL_GEST_TESTATA.ID AS FK_BOLLGEST_ID, ROW_NUMBER() OVER(PARTITION BY BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE, BOLL_GEST_DETT_AUTORIZZ.ID ORDER BY BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE ASC, BOLL_GEST_DETT_AUTORIZZ.ID ASC) AS RNUM FROM BOLL_GEST_TESTATA INNER JOIN BOLL_GEST_DETTAGLIO ON BOLL_GEST_TESTATA.IDCOMUNE = BOLL_GEST_DETTAGLIO.IDCOMUNE AND BOLL_GEST_TESTATA.ID = BOLL_GEST_DETTAGLIO.FK_BOLLGEST_ID INNER JOIN BOLL_GEST_DETT_AUTORIZZ ON BOLL_GEST_DETTAGLIO.IDCOMUNE = BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE AND BOLL_GEST_DETTAGLIO.ID = BOLL_GEST_DETT_AUTORIZZ.FK_BOLLGESTDET_ID AND BOLL_GEST_DETT_AUTORIZZ.FK_BOLLGEST_ID IS NULL) WHERE RNUM = 1) TESTATA ON (BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE = TESTATA.IDCOMUNE AND BOLL_GEST_DETT_AUTORIZZ.ID = TESTATA.ID) WHEN MATCHED THEN UPDATE SET BOLL_GEST_DETT_AUTORIZZ.FK_BOLLGEST_ID = TESTATA.FK_BOLLGEST_ID;
MERGE INTO BOLL_GEST_DETT_RATE USING (SELECT IDCOMUNE, ID, FK_BOLLGEST_ID, RNUM FROM (SELECT BOLL_GEST_DETT_RATE.IDCOMUNE, BOLL_GEST_DETT_RATE.ID, BOLL_GEST_TESTATA.ID AS FK_BOLLGEST_ID, ROW_NUMBER() OVER(PARTITION BY BOLL_GEST_DETT_RATE.IDCOMUNE, BOLL_GEST_DETT_RATE.ID ORDER BY BOLL_GEST_DETT_RATE.IDCOMUNE ASC, BOLL_GEST_DETT_RATE.ID ASC) AS RNUM FROM BOLL_GEST_TESTATA INNER JOIN BOLL_GEST_DETTAGLIO ON BOLL_GEST_TESTATA.IDCOMUNE = BOLL_GEST_DETTAGLIO.IDCOMUNE AND BOLL_GEST_TESTATA.ID = BOLL_GEST_DETTAGLIO.FK_BOLLGEST_ID INNER JOIN BOLL_GEST_DETT_RATE ON BOLL_GEST_DETTAGLIO.IDCOMUNE = BOLL_GEST_DETT_RATE.IDCOMUNE AND BOLL_GEST_DETTAGLIO.ID = BOLL_GEST_DETT_RATE.FK_BOLLGESTDET_ID AND BOLL_GEST_DETT_RATE.FK_BOLLGEST_ID IS NULL) WHERE RNUM = 1) TESTATA ON (BOLL_GEST_DETT_RATE.IDCOMUNE = TESTATA.IDCOMUNE AND BOLL_GEST_DETT_RATE.ID = TESTATA.ID) WHEN MATCHED THEN UPDATE SET BOLL_GEST_DETT_RATE.FK_BOLLGEST_ID = TESTATA.FK_BOLLGEST_ID;
MERGE INTO BOLL_GEST_ISTANZEONERI USING (SELECT IDCOMUNE, ID, FK_BOLLGEST_ID, RNUM FROM (SELECT BOLL_GEST_ISTANZEONERI.IDCOMUNE, BOLL_GEST_ISTANZEONERI.ID, BOLL_GEST_TESTATA.ID AS FK_BOLLGEST_ID, ROW_NUMBER() OVER(PARTITION BY BOLL_GEST_ISTANZEONERI.IDCOMUNE, BOLL_GEST_ISTANZEONERI.ID ORDER BY BOLL_GEST_ISTANZEONERI.IDCOMUNE ASC, BOLL_GEST_ISTANZEONERI.ID ASC) AS RNUM FROM BOLL_GEST_TESTATA INNER JOIN BOLL_GEST_DETTAGLIO ON BOLL_GEST_TESTATA.IDCOMUNE = BOLL_GEST_DETTAGLIO.IDCOMUNE AND BOLL_GEST_TESTATA.ID = BOLL_GEST_DETTAGLIO.FK_BOLLGEST_ID INNER JOIN BOLL_GEST_ISTANZEONERI ON BOLL_GEST_DETTAGLIO.IDCOMUNE = BOLL_GEST_ISTANZEONERI.IDCOMUNE AND BOLL_GEST_DETTAGLIO.ID = BOLL_GEST_ISTANZEONERI.FK_BOLLGESTDET_ID AND BOLL_GEST_ISTANZEONERI.FK_BOLLGEST_ID IS NULL) WHERE RNUM = 1) TESTATA ON (BOLL_GEST_ISTANZEONERI.IDCOMUNE = TESTATA.IDCOMUNE AND BOLL_GEST_ISTANZEONERI.ID = TESTATA.ID) WHEN MATCHED THEN UPDATE SET BOLL_GEST_ISTANZEONERI.FK_BOLLGEST_ID = TESTATA.FK_BOLLGEST_ID;
MERGE INTO BOLL_GEST_MERCATI_DETT USING (SELECT IDCOMUNE, ID, FK_BOLLGEST_ID, RNUM FROM (SELECT BOLL_GEST_MERCATI_DETT.IDCOMUNE, BOLL_GEST_MERCATI_DETT.ID, BOLL_GEST_TESTATA.ID AS FK_BOLLGEST_ID, ROW_NUMBER() OVER(PARTITION BY BOLL_GEST_MERCATI_DETT.IDCOMUNE, BOLL_GEST_MERCATI_DETT.ID ORDER BY BOLL_GEST_MERCATI_DETT.IDCOMUNE ASC, BOLL_GEST_MERCATI_DETT.ID ASC) AS RNUM FROM BOLL_GEST_TESTATA INNER JOIN BOLL_GEST_DETTAGLIO ON BOLL_GEST_TESTATA.IDCOMUNE = BOLL_GEST_DETTAGLIO.IDCOMUNE AND BOLL_GEST_TESTATA.ID = BOLL_GEST_DETTAGLIO.FK_BOLLGEST_ID INNER JOIN BOLL_GEST_DETT_AUTORIZZ ON BOLL_GEST_DETTAGLIO.IDCOMUNE = BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE AND BOLL_GEST_DETTAGLIO.ID = BOLL_GEST_DETT_AUTORIZZ.FK_BOLLGESTDET_ID INNER JOIN BOLL_GEST_MERCATI_DETT ON BOLL_GEST_DETT_AUTORIZZ.IDCOMUNE = BOLL_GEST_MERCATI_DETT.IDCOMUNE AND BOLL_GEST_DETT_AUTORIZZ.ID = BOLL_GEST_MERCATI_DETT.FK_ID_GEST_AUTORIZZAZIONI AND BOLL_GEST_MERCATI_DETT.FK_BOLLGEST_ID IS NULL) WHERE RNUM = 1) TESTATA ON (BOLL_GEST_MERCATI_DETT.IDCOMUNE = TESTATA.IDCOMUNE AND BOLL_GEST_MERCATI_DETT.ID = TESTATA.ID) WHEN MATCHED THEN UPDATE SET BOLL_GEST_MERCATI_DETT.FK_BOLLGEST_ID = TESTATA.FK_BOLLGEST_ID;
MERGE INTO BOLL_GEST_ONERI_SEQUENCE USING (SELECT IDCOMUNE, ID_BOLLEGEST_DETT, ID_BOLLEGEST_ONERI, FK_BOLLGEST_ID, RNUM FROM (SELECT BOLL_GEST_ONERI_SEQUENCE.IDCOMUNE, BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_DETT, BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_ONERI, BOLL_GEST_TESTATA.ID AS FK_BOLLGEST_ID, ROW_NUMBER() OVER(PARTITION BY BOLL_GEST_ONERI_SEQUENCE.IDCOMUNE, BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_DETT, BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_ONERI ORDER BY BOLL_GEST_ONERI_SEQUENCE.IDCOMUNE ASC, BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_DETT ASC, BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_ONERI ASC) AS RNUM FROM BOLL_GEST_TESTATA INNER JOIN BOLL_GEST_DETTAGLIO ON BOLL_GEST_TESTATA.IDCOMUNE = BOLL_GEST_DETTAGLIO.IDCOMUNE AND BOLL_GEST_TESTATA.ID = BOLL_GEST_DETTAGLIO.FK_BOLLGEST_ID INNER JOIN BOLL_GEST_ONERI_SEQUENCE ON BOLL_GEST_DETTAGLIO.IDCOMUNE = BOLL_GEST_ONERI_SEQUENCE.IDCOMUNE AND BOLL_GEST_DETTAGLIO.ID = BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_DETT AND BOLL_GEST_ONERI_SEQUENCE.FK_BOLLGEST_ID IS NULL) WHERE RNUM = 1) TESTATA ON (BOLL_GEST_ONERI_SEQUENCE.IDCOMUNE = TESTATA.IDCOMUNE AND BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_DETT = TESTATA.ID_BOLLEGEST_DETT AND BOLL_GEST_ONERI_SEQUENCE.ID_BOLLEGEST_ONERI = TESTATA.ID_BOLLEGEST_ONERI) WHEN MATCHED THEN UPDATE SET BOLL_GEST_ONERI_SEQUENCE.FK_BOLLGEST_ID = TESTATA.FK_BOLLGEST_ID;
COMMIT;

ALTER TABLE BOLL_GEST_DETT_AUTORIZZ MODIFY FK_BOLLGEST_ID NUMBER(4,0) NOT NULL;
